import { GoogleGenAI, Chat, Type, Blob as GenAIBlob } from "@google/genai";
import { CHATBOT_SYSTEM_INSTRUCTION } from '../constants';
import { EstimateFormData, ChatbotResponse } from '../types';

let ai: GoogleGenAI;
let chat: Chat;

const getAI = () => {
  if (!ai) {
    if (!process.env.API_KEY) {
      throw new Error("API_KEY environment variable not set");
    }
    ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }
  return ai;
};

const initializeChat = () => {
    if (!chat) {
        const aiInstance = getAI();
        chat = aiInstance.chats.create({
            model: 'gemini-2.5-flash',
            config: {
                systemInstruction: CHATBOT_SYSTEM_INSTRUCTION,
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        reply: { type: Type.STRING },
                        suggestedQuestions: {
                            type: Type.ARRAY,
                            items: { type: Type.STRING }
                        }
                    },
                    required: ["reply", "suggestedQuestions"]
                }
            },
        });
    }
}

export const sendMessageToChatbot = async (message: string, imageFile?: File): Promise<ChatbotResponse> => {
    try {
        initializeChat();

        let response;
        if (imageFile) {
            const imagePart = await fileToGenerativePart(imageFile);
            // Construct a multipart message
            response = await chat.sendMessage({ 
                message: { 
                    role: 'user', 
                    parts: [imagePart, { text: message || "Analyze this image." }] 
                } 
            });
        } else {
             response = await chat.sendMessage({ message });
        }

        const jsonString = response.text?.trim() || "{}";

        let parsedResult: any;
        try {
            parsedResult = JSON.parse(jsonString);
        } catch (parseError) {
            console.error("Error parsing JSON response from AI:", parseError, "Raw response:", jsonString);
            return {
                reply: jsonString || "I'm sorry, I received an unusual response. Please try again.",
                suggestedQuestions: ["What services do you offer?", "Can I get a free estimate?", "Do you handle storm damage?"]
            };
        }

        const reply = typeof parsedResult.reply === 'string' ? parsedResult.reply : "I'm sorry, I couldn't formulate a proper response. Please ask me something else.";
        const suggestedQuestions = Array.isArray(parsedResult.suggestedQuestions)
            ? parsedResult.suggestedQuestions.filter((q: any): q is string => typeof q === 'string')
            : [];

        return {
            reply,
            suggestedQuestions
        };

    } catch (error) {
        console.error("Error sending message to chatbot API:", error);
        return {
            reply: "I'm sorry, I'm having trouble connecting right now. Please try again in a moment.",
            suggestedQuestions: ["What services do you offer?", "How can I contact support?"]
        };
    }
};

const fileToGenerativePart = async (file: File) => {
    const base64EncodedDataPromise = new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(file);
    });
    return {
        inlineData: { data: await base64EncodedDataPromise, mimeType: file.type },
    };
}

export const analyzeRoofImage = async (imageFile: File): Promise<string> => {
    try {
        const aiInstance = getAI();
        const imagePart = await fileToGenerativePart(imageFile);
        const textPart = {
            text: `Analyze the provided image of a roof. As a roofing expert, identify potential issues such as missing, cracked, or curled shingles, algae or moss growth, damaged flashing, or signs of water damage. Provide a bullet-point summary of your findings using asterisks, followed by a 'Recommendation' paragraph. Keep the tone helpful and professional. If the image is not a roof, state that you cannot analyze it and ask for a picture of a roof.`
        };

        const response = await aiInstance.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: { parts: [imagePart, textPart] },
        });

        return response.text || "No analysis could be generated.";
    } catch (error) {
        console.error("Error analyzing roof image:", error);
        throw error;
    }
};

export const analyzeRoofVideo = async (videoFile: File): Promise<string> => {
    try {
        const aiInstance = getAI();
        const videoPart = await fileToGenerativePart(videoFile);
        const textPart = {
            text: `Analyze the provided video of a roof. As a roofing expert, carefully review the footage. Identify potential issues such as missing, cracked, or curled shingles, algae or moss growth, damaged flashing, signs of water damage, or any other visible defects. Provide a bullet-point summary of your findings using asterisks, followed by a 'Recommendation' paragraph. Keep the tone helpful and professional. If the video does not show a roof, state that you cannot analyze it and ask for a video of a roof.`
        };

        const response = await aiInstance.models.generateContent({
            model: 'gemini-2.5-pro', 
            contents: { parts: [videoPart, textPart] },
        });

        return response.text || "No video analysis could be generated.";
    } catch (error) {
        console.error("Error analyzing roof video:", error);
        throw error;
    }
};

export const getAIEstimate = async (formData: EstimateFormData) => {
    try {
        const aiInstance = getAI();
        const prompt = `
            You are an expert AI roofing cost estimator.
            Generate a rough, non-binding cost estimate range for a roof project based on the following data.
            Project Data:
            - Roof Material: ${formData.roofType}
            - Square Footage: ${formData.sqft} sq ft
            - Roof Slope: ${formData.slope}
            - Number of Stories: ${formData.stories}
            - Location Zip Code: ${formData.zipCode}

            Please provide the estimate in a JSON format with 'lowEstimate', 'highEstimate', and 'explanation'.
        `;

        const response = await aiInstance.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        lowEstimate: { type: Type.NUMBER },
                        highEstimate: { type: Type.NUMBER },
                        explanation: { type: Type.STRING },
                    },
                    required: ["lowEstimate", "highEstimate", "explanation"],
                },
            },
        });

        const jsonString = response.text?.trim() || "{}";
        return JSON.parse(jsonString);
    } catch (error) {
        console.error("Error getting AI estimate:", error);
        throw error;
    }
};

export const generateHeroImage = async (prompt: string): Promise<string> => {
    try {
        const aiInstance = getAI();
        const fullPrompt = `A beautiful, photorealistic image of a house roof for a roofing company website hero section. Prompt: "${prompt}"`;

        const response = await aiInstance.models.generateImages({
            model: 'imagen-4.0-generate-001',
            prompt: fullPrompt,
            config: {
              numberOfImages: 1,
              outputMimeType: 'image/jpeg',
              aspectRatio: '16:9',
            },
        });

        const base64ImageBytes = response.generatedImages?.[0]?.image?.imageBytes;
        if (!base64ImageBytes) throw new Error("No image data received from API.");
        return `data:image/jpeg;base64,${base64ImageBytes}`;
    } catch (error) {
        console.error("Error generating hero image:", error);
        throw error;
    }
};

export const generateHeroVideo = async (prompt: string): Promise<string> => {
    try {
        const aiInstance = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // Use the 'fast' model as it might have higher availability/different quota limits
        let operation = await aiInstance.models.generateVideos({
          model: 'veo-3.1-fast-generate-preview',
          prompt: prompt,
          config: {
            numberOfVideos: 1,
            resolution: '1080p',
            aspectRatio: '16:9'
          }
        });

        while (!operation.done) {
          await new Promise(resolve => setTimeout(resolve, 5000));
          operation = await aiInstance.operations.getVideosOperation({operation: operation});
        }

        if (operation.error) {
            throw operation.error;
        }

        const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (!downloadLink) {
            throw new Error("Video generation completed but no video URI was returned.");
        }

        const separator = downloadLink.includes('?') ? '&' : '?';
        const response = await fetch(`${downloadLink}${separator}key=${process.env.API_KEY}`);

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(`Failed to fetch video: ${response.status} - ${errorText}`);
        }

        const blob = await response.blob();
        return URL.createObjectURL(blob);
    } catch (error: any) {
        console.error("Error generating hero video:", error);
        throw error;
    }
};

function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function createBlob(data: Float32Array): GenAIBlob {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

import React, { useState, useRef, useEffect } from 'react';
import VoiceAgentOrb, { VoiceAgentHandle } from './VoiceAgentOrb';
import { generateHeroVideo } from '../services/geminiService';
import { VideoCameraIcon } from './Icon';

interface HeroProps {
    onScheduleClick: () => void;
    onEstimateClick: () => void;
    voiceAgentRef: React.Ref<VoiceAgentHandle>;
}

const Hero: React.FC<HeroProps> = ({ onScheduleClick, onEstimateClick, voiceAgentRef }) => {
  const [heroImageUrl] = useState('https://images.pexels.com/photos/164558/pexels-photo-164558.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=2');
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [isGeneratingVideo, setIsGeneratingVideo] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    if (videoUrl && videoRef.current) {
        videoRef.current.play().catch(e => console.error("Autoplay failed:", e));
    }
  }, [videoUrl]);

  const handleModalClick = (e: React.MouseEvent<HTMLAnchorElement>, handler: () => void) => {
    e.preventDefault();
    handler();
  };

  const generateVideo = async (retryCount = 0) => {
      try {
        const prompt = "A professional, high-quality cinematic video for Elite Roofing. A sunny day showing a beautiful home with a pristine, durable roof. A friendly roofing professional in a uniform is shaking hands with a happy homeowner in front of the house, symbolizing trust, reliability, and customer satisfaction. An Elite Roofing truck is visible in the driveway. The scene is calm, reliable, and premium. 4k resolution, highly detailed, smooth motion, architectural style.";
        const url = await generateHeroVideo(prompt);
        setVideoUrl(url);
      } catch (error: any) {
        console.error("Video generation failed:", error);

        let errorMsg = error.message || '';
        try {
            if (typeof error === 'object') {
                errorMsg += ' ' + JSON.stringify(error);
            }
        } catch(e) {}

        const aistudio = (window as any).aistudio;

        // Handle Quota Exhausted (429) specifically
        if (errorMsg.includes("429") || errorMsg.includes("RESOURCE_EXHAUSTED") || errorMsg.includes("quota")) {
            alert("You've reached the API rate limit or quota for video generation. Please check your project's billing and plan at https://ai.google.dev/pricing or wait a few minutes before trying again.");
            return;
        }

        // Handle API key issues
        if (errorMsg.includes("API key") || errorMsg.includes("expired") || errorMsg.includes("400") || errorMsg.includes("INVALID_ARGUMENT") || errorMsg.includes("403")) {
             if (aistudio && retryCount < 1) { 
                 const retry = window.confirm("The API key appears to be invalid or expired. Would you like to select a new key and try again?");
                 if (retry) {
                     const success = await aistudio.openSelectKey();
                     if (success) {
                         await generateVideo(retryCount + 1);
                         return;
                     }
                 }
             } else {
                 alert("API Key expired or invalid. Please refresh the page to reset the key selection.");
             }
        } else {
             alert("Failed to generate video background. " + (error.message || "Please try again later."));
        }
      }
  };

  const handleGenerateVideo = async () => {
    if (isGeneratingVideo) return;
    setIsGeneratingVideo(true);
    const aistudio = (window as any).aistudio;
    try {
        if (aistudio) {
             const hasKey = await aistudio.hasSelectedApiKey();
             if (!hasKey) {
                 const success = await aistudio.openSelectKey();
                 if (!success) {
                     setIsGeneratingVideo(false);
                     return;
                 }
             }
        }

        await generateVideo();

    } catch (error) {
        console.error("Error in generation flow:", error);
    } finally {
        setIsGeneratingVideo(false);
    }
  };

  return (
    <section className="relative bg-gray-900 text-white py-20 sm:py-24 md:py-32 min-h-[550px] sm:min-h-[600px] flex items-center overflow-hidden">
      {/* Background Layer */}
      <div className="absolute inset-0 z-0">
          {videoUrl ? (
             <video 
                ref={videoRef}
                key={videoUrl}
                autoPlay 
                loop 
                muted 
                playsInline 
                className="absolute inset-0 w-full h-full object-cover transition-opacity duration-1000"
                src={videoUrl}
                onLoadedData={() => console.log("Video loaded")}
                onError={(e) => console.error("Video playback error", e)}
             />
          ) : (
            <div
                className="absolute inset-0 bg-cover bg-center transition-all duration-1000"
                style={{ backgroundImage: `url('${heroImageUrl}')` }}
            ></div>
          )}
           <div className="absolute inset-0 bg-gradient-to-b from-gray-900/80 via-gray-900/60 to-gray-900/90"></div>
      </div>

      {/* Content Layer */}
      <div className="container mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        <div className="max-w-4xl text-center mx-auto flex flex-col items-center">
          <h1 className="text-3xl sm:text-4xl md:text-6xl lg:text-7xl font-extrabold leading-tight mb-4 sm:mb-6 tracking-tight drop-shadow-lg">
            The Future of Roofing <br className="hidden md:block" /> is Here.
          </h1>
          <p className="text-base sm:text-lg md:text-2xl text-gray-200 mb-8 sm:mb-10 max-w-2xl mx-auto font-light leading-relaxed drop-shadow-md">
            Experience seamless service with our AI-powered tools. Get instant estimates, book appointments online, and protect your home with the best in the business.
          </p>

          <div className="flex flex-col sm:flex-row gap-4 justify-center items-center w-full sm:w-auto">
            <a
              href="#estimate"
              onClick={(e) => handleModalClick(e, onEstimateClick)}
              className="w-full sm:w-auto bg-blue-600 text-white font-bold py-3 sm:py-4 px-6 sm:px-8 rounded-full shadow-lg hover:bg-blue-700 hover:shadow-blue-600/50 transition-all duration-300 transform hover:-translate-y-1 text-base sm:text-lg min-w-[200px]"
            >
              Get a Free Quote
            </a>

            <div className="hidden md:block">
                 <VoiceAgentOrb ref={voiceAgentRef} />
            </div>

            <a
              href="#schedule"
              onClick={(e) => handleModalClick(e, onScheduleClick)}
              className="w-full sm:w-auto bg-white/10 backdrop-blur-sm border-2 border-white text-white font-bold py-3 sm:py-3.5 px-6 sm:px-8 rounded-full shadow-lg hover:bg-white hover:text-gray-900 transition-all duration-300 transform hover:-translate-y-1 text-base sm:text-lg min-w-[200px]"
            >
              Book a Consultation
            </a>
          </div>

           <div className="mt-8 md:hidden scale-90 sm:scale-100">
                 <VoiceAgentOrb ref={voiceAgentRef} />
            </div>

           <div className="mt-8">
            <a
              href="tel:1-800-555-ROOF"
              className="inline-flex items-center gap-2 text-red-400 font-bold hover:text-red-300 transition-colors animate-pulse text-sm sm:text-base"
            >
              <span className="w-2 h-2 bg-red-500 rounded-full"></span>
              For 24/7 Emergency Service, Call Now
            </a>
           </div>
        </div>

        <div className="absolute top-4 right-4 z-20">
            <button
                onClick={handleGenerateVideo}
                disabled={isGeneratingVideo}
                className="flex items-center gap-2 bg-black/40 backdrop-blur-md border border-white/10 text-white text-[10px] sm:text-xs font-semibold py-1.5 px-2 sm:py-2 sm:px-3 rounded-full hover:bg-black/60 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                title="Generate a custom AI video background for this section"
            >
                {isGeneratingVideo ? (
                    <>
                        <div className="w-3 h-3 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        Generating...
                    </>
                ) : videoUrl ? (
                    <>
                         <VideoCameraIcon className="w-3 h-3 sm:w-4 sm:h-4" />
                         Regenerate
                    </>
                ) : (
                    <>
                         <VideoCameraIcon className="w-3 h-3 sm:w-4 sm:h-4" />
                        Generate AI Video
                    </>
                )}
            </button>
        </div>
      </div>
    </section>
  );
};

export default Hero;
